import{Router}from"./router.js";import{Home,Projetos,Cadastro,Contato,NotFound}from"./templates.js";import{initFormEnhancements}from"./forms.js";function hijackNav(t){document.addEventListener("click",o=>{const e=o.target.closest("a,button.nav-link--button");if(e){if(e.matches("button.nav-link--button"))return o.preventDefault(),void t.go("/projetos");if(e.matches(".dropdown-link")){const n=e.getAttribute("href")||"";if(n.includes("projetos.html#voluntariado"))return o.preventDefault(),void t.go("/projetos",{scroll:"voluntariado"});if(n.includes("projetos.html#como-doar"))return o.preventDefault(),void t.go("/projetos",{scroll:"como-doar"})}if(e.matches(".nav-link")){const n=e.getAttribute("href")||"";n.endsWith("index.html")?(o.preventDefault(),t.go("/")):n.includes("projetos.html")?(o.preventDefault(),t.go("/projetos")):n.includes("cadastro.html")?(o.preventDefault(),t.go("/cadastro")):n.includes("contato.html")&&(o.preventDefault(),t.go("/contato"))}}})}function setActive(t){document.querySelectorAll(".nav-link, .nav-link--button").forEach(t=>t.classList.remove("is-active")),"/"===t?document.querySelector('.nav-link[href="index.html"]')?.classList.add("is-active"):"/projetos"===t?document.querySelector(".nav-link--button")?.classList.add("is-active"):"/cadastro"===t?document.querySelector('.nav-link[href="cadastro.html"]')?.classList.add("is-active"):"/contato"===t&&document.querySelector('.nav-link[href="index.html#contato"], .nav-link[href="contato.html"]')?.classList.add("is-active")}function scrollIfRequested(t){const o=t?.get?.("scroll");o&&requestAnimationFrame(()=>{const t=document.getElementById(o);t&&t.scrollIntoView({behavior:"smooth",block:"start"})})}const mount=document.getElementById("app"),router=new Router({mount:mount,routes:{"/":Home,"/projetos":Projetos,"/cadastro":()=>{const t=Cadastro();return queueMicrotask(()=>initFormEnhancements(mount)),t},"/contato":Contato,"/404":NotFound}});hijackNav(router),document.addEventListener("spa:render",t=>{const{path:o,query:e}=t.detail;setActive(o),"/projetos"===o&&scrollIfRequested(e)}),location.hash||(location.hash="/");